package week_08.oop.assigment_problems;
import java.util.*;
public class ElectiveSeatRush {
 interface CreditPolicy{int limit();}
 static class Regular implements CreditPolicy{public int limit(){return 24;}}static class Honors implements CreditPolicy{public int limit(){return 28;}}static class Exchange implements CreditPolicy{public int limit(){return 20;}}
 static class Student{String name;CreditPolicy policy;int credits;Student(String n,CreditPolicy p,int c){name=n;policy=p;credits=c;}}
 static class Elective{String name;int credits,capacity;List<Student> enrolled=new ArrayList<>();Queue<Student> waitlist=new ArrayDeque<>();Set<String> known=new HashSet<>();Elective(String n,int c,int cap){name=n;credits=c;capacity=cap;}String enroll(Student s){if(!known.add(s.name))return s.name+" already enrolled or waitlisted.";if(s.credits+credits>s.policy.limit()){known.remove(s.name);return "Enrollment failed: "+s.name+" would exceed credit limit ("+(s.credits+credits)+"/"+s.policy.limit()+").";}if(enrolled.size()<capacity){enrolled.add(s);s.credits+=credits;return s.name+" enrolled in "+name+" (credits: "+s.credits+"/"+s.policy.limit()+").";}waitlist.add(s);return name+" is full. "+s.name+" added to waitlist (position "+waitlist.size()+").";}String drop(Student s){if(!enrolled.remove(s))return s.name+" is not enrolled.";s.credits-=credits;known.remove(s.name);String msg=s.name+" dropped "+name+" (credits: "+s.credits+"/"+s.policy.limit()+").";while(!waitlist.isEmpty()){Student next=waitlist.peek();if(next.credits+credits<=next.policy.limit()){waitlist.remove();next.credits+=credits;enrolled.add(next);msg+=" "+next.name+" promoted from waitlist and enrolled.";break;}waitlist.remove();known.remove(next.name);}return msg;}}
 public static void main(String[]args){Elective e=new Elective("Cloud Computing",4,2);Student a=new Student("Asha",new Regular(),20),r=new Student("Ravi",new Honors(),22),n=new Student("Neha",new Exchange(),12),k=new Student("Kiran",new Regular(),22);System.out.println(e.enroll(a));System.out.println(e.enroll(r));System.out.println(e.enroll(n));System.out.println(e.enroll(k));System.out.println(e.drop(a));}
}